:root{--navy:#111b34;--navy2:#1b2a4a;--ink:#1b2942;--muted:#7a879d;--line:#e7ebf2;--bg:#f4f6fa;--card:#fff;--accent:#4358e8;--green:#19a36f;--orange:#f39a2f;--red:#db4d55;--gold:#d69b28;--shadow:0 14px 40px rgba(20,35,70,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Arial,sans-serif}.page{max-width:1580px;margin:auto;padding:22px}.hero{background:linear-gradient(135deg,#111b34,#243b68);color:#fff;border-radius:22px;padding:22px 24px;display:flex;justify-content:space-between;align-items:center;gap:18px;box-shadow:0 18px 45px rgba(17,27,52,.18);margin-bottom:16px}.hero-left{display:flex;align-items:center;gap:14px}.brand{width:48px;height:48px;border-radius:15px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.16);display:grid;place-items:center;font-weight:950;letter-spacing:-1px}.eyebrow{font-size:9px;letter-spacing:1.8px;font-weight:900;color:#aebdff}.hero h1{font-size:25px;margin:3px 0 5px}.hero p{font-size:11px;margin:0;color:#d3dbeb}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid #dce2ec;background:#fff;color:var(--ink);padding:10px 14px;border-radius:11px;font-weight:850;font-size:11px;cursor:pointer}.btn.dark{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.2);color:#fff}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn:hover{transform:translateY(-1px)}
