.main{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:16px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow);overflow:hidden}.card-head{padding:17px 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}.card-head h2{font-size:13px;margin:0}.card-head p{font-size:9px;color:var(--muted);margin:4px 0 0}.pill{font-size:9px;font-weight:900;padding:7px 9px;border-radius:8px;background:#f0f2f7;color:#59657c}.map{padding:17px}.front{height:38px;border-radius:11px;border:1px dashed #cbd3e0;background:#fafbfe;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:950;letter-spacing:1.5px;color:#8a95a8;margin-bottom:13px}.shift{border:1px solid var(--line);border-radius:15px;margin-bottom:12px;overflow:hidden}.shift:last-child{margin-bottom:0}.shift-head{padding:12px 14px;background:#fbfcfe;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.shift-title{display:flex;align-items:center;gap:9px}.dot{width:9px;height:9px;border-radius:50%}.dot.m{background:var(--green)}.dot.e{background:var(--orange)}.dot.f{background:var(--red)}.shift-title b{font-size:11px}.shift-title small{display:block;color:var(--muted);font-size:8px;margin-top:2px}.shift-stat{font-size:9px;font-weight:850;color:#68758c}.seat-grid{padding:14px;display:grid;grid-template-columns:repeat(10,minmax(38px,1fr));gap:7px}.row-label{grid-column:1/-1;font-size:8px;font-weight:950;color:#a0a9b9;letter-spacing:1.1px;padding-top:2px}.aisle{grid-column:1/-1;border-top:1px dashed #e2e6ee;height:4px;margin:2px 0}.seat{height:58px;border-radius:12px;border:1px solid #dce2ec;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;cursor:pointer;transition:.15s;overflow:hidden;position:relative}.seat:hover{transform:translateY(-2px);box-shadow:0 9px 20px rgba(20,35,70,.13)}.seat .chair{font-size:17px;line-height:17px}.seat b{font-size:9px}.seat small{font-size:7px;max-width:90%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.seat.available{color:#5c6a81;background:#fbfcfe}.seat.occupied.morning{background:#e7f8f0;border-color:#8bd1b2;color:#106d4b}.seat.occupied.evening{background:#fff1df;border-color:#efbd7a;color:#8b4d08}.seat.occupied.full{background:#fbe7e8;border-color:#e6a0a5;color:#972f35}.seat.reserved{background:#fff8df;border-color:#e6c66d;color:#8a650c}.seat.dim{display:none}.seat.hit{outline:2px solid var(--accent);outline-offset:2px}
.side{display:flex;flex-direction:column;gap:16px}.legend{padding:16px}.legend-row{display:flex;align-items:center;gap:8px;font-size:10px;margin:10px 0;color:#5f6c83}.sw{width:13px;height:13px;border-radius:4px;border:1px solid #d7dde8}.sw.free{background:#fbfcfe}.sw.m{background:#e7f8f0;border-color:#8bd1b2}.sw.e{background:#fff1df;border-color:#efbd7a}.sw.f{background:#fbe7e8;border-color:#e6a0a5}.sw.r{background:#fff8df;border-color:#e6c66d}.locker-head{display:flex;align-items:center;gap:10px}.locker-icon{width:34px;height:34px;border-radius:10px;background:#f8f0dc;display:grid;place-items:center}.locker-map{padding:15px;display:grid;grid-template-columns:repeat(7,minmax(34px,1fr));gap:6px}.locker{height:40px;border-radius:9px;border:1px solid #dce2ec;background:#f9fafc;display:grid;place-items:center;cursor:pointer;font-size:9px;font-weight:900;color:#65738a}.locker.occupied{background:#e8eefc;border-color:#9eaff2;color:#3148ae}.locker.expired{background:#fff0f0;border-color:#e5aaaa;color:#a53a3f}.locker:hover{transform:translateY(-1px)}.holder-list{padding:0 16px 14px}.holder{display:flex;align-items:center;gap:9px;padding:11px 0;border-top:1px solid var(--line)}.avatar{width:32px;height:32px;border-radius:10px;background:#eef1ff;color:var(--accent);display:grid;place-items:center;font-size:11px;font-weight:950}.holder-main{min-width:0;flex:1}.holder-main b{display:block;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.holder-main small{display:block;font-size:8px;color:var(--muted);margin-top:2px}.release{width:28px;height:28px;border:0;border-radius:8px;background:#fcebed;color:var(--red);font-weight:950;cursor:pointer}.empty{padding:16px;color:var(--muted);font-size:10px}
.modalback{position:fixed;inset:0;background:rgba(8,17,37,.62);display:grid;place-items:center;padding:16px;z-index:100}.modal{width:min(540px,100%);background:#fff;border-radius:18px;overflow:hidden;box-shadow:0 28px 80px rgba(0,0,0,.28)}.modalhead{padding:16px 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.modalhead h3{font-size:14px;margin:0}.close{border:0;width:31px;height:31px;border-radius:9px;background:#f2f4f8;cursor:pointer;font-size:17px}.form{padding:18px}.profile{display:flex;align-items:center;gap:12px;border:1px solid #e2e7f0;border-radius:14px;padding:13px;background:linear-gradient(135deg,#f6f8ff,#fff);margin-bottom:13px}.profile-avatar{width:48px;height:48px;border-radius:14px;background:var(--navy);color:#fff;display:grid;place-items:center;font-size:18px;font-weight:950}.profile-main{min-width:0;flex:1}.profile-name{font-size:15px;font-weight:950}.profile-meta{font-size:9px;color:var(--muted);margin-top:3px}.profile-tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}.profile-tags span{font-size:8px;font-weight:900;background:#edf0f7;padding:4px 6px;border-radius:6px;color:#59657c}.booked{font-size:8px;font-weight:950;color:#0e6a48;background:#e4f7ed;border:1px solid #b8e3cc;padding:5px 7px;border-radius:7px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.field{margin-bottom:11px}.field label{display:block;font-size:9px;font-weight:950;margin-bottom:6px;color:#59657c}.field input{width:100%;height:40px;border:1px solid #d9dfeb;border-radius:9px;padding:0 10px;outline:0;font-size:11px}.modalfoot{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.toast{position:fixed;right:20px;bottom:20px;background:var(--navy);color:#fff;padding:11px 14px;border-radius:11px;font-size:10px;font-weight:850;display:none;z-index:200}
