</style></head><body>
<div class="page">
<section class="hero"><div class="hero-left"><div class="brand">AR</div><div><div class="eyebrow">AR LIBRARY · OPERATIONS</div><h1>Seat & Locker Command Center</h1><p>Live seating, member assignment and locker management in one professional workspace.</p></div></div><div class="actions"><button class="btn dark" onclick="location.href='index.php'">← Dashboard</button><button class="btn primary" onclick="load()">↻ Refresh Live Data</button></div></section>
<div id="kpis" class="kpis"></div>
<section class="controls"><div class="search"><span>⌕</span><input id="search" placeholder="Search seat number, member name or ID…" oninput="applyFilters()"></div><div class="tabs"><button class="tab active" data-f="all" onclick="setFilter('all',this)">All Seats</button><button class="tab" data-f="available" onclick="setFilter('available',this)">Available</button><button class="tab" data-f="occupied" onclick="setFilter('occupied',this)">Occupied</button><button class="tab" data-f="reserved" onclick="setFilter('reserved',this)">Reserved</button></div><div class="control-note">Click any seat to view or manage assignment</div></section>
<div class="main"><main class="card"><div class="card-head"><div><h2>LIVE LIBRARY FLOOR MAP</h2><p>live-seat visual layout · availability updates from your MongoDB database</p></div><span class="pill" id="capacity">76 SEATS</span></div><div class="map"><div class="front">FRONT / BOARD · RECEPTION & ENTRANCE</div><div id="shifts"></div></div></main>
<aside class="side"><section class="card"><div class="card-head"><div class="locker-head"><div class="locker-icon">🔐</div><div><h2>LOCKER MANAGEMENT</h2><p>Assign, monitor and release lockers</p></div></div><span class="pill" id="lockerSummary">Loading…</span></div><div id="lockerLayout" class="locker-map"></div><div id="lockerHolders" class="holder-list"></div></section>
<section class="card"><div class="card-head"><div><h2>STATUS GUIDE</h2><p>Quick visual reference</p></div></div><div class="legend"><div class="legend-row"><i class="sw free"></i> Available</div><div class="legend-row"><i class="sw m"></i> Morning occupied</div><div class="legend-row"><i class="sw e"></i> Evening occupied</div><div class="legend-row"><i class="sw f"></i> Full Day occupied</div><div class="legend-row"><i class="sw r"></i> Reserved</div></div></section></aside></div>
</div><div id="modal"></div><div id="toast" class="toast"></div>
<script>
const seatNativeFetch=window.fetch.bind(window);
window.fetch=(input,init={})=>{const method=String(init.method||'GET').toUpperCase();if(method!=='GET'&&method!=='HEAD'){const h=new Headers(init.headers||{});const t=document.querySelector('meta[name="csrf-token"]')?.content||'';if(t)h.set('X-CSRF-Token',t);init.headers=h;}return seatNativeFetch(input,init);};
let rows=[],lockers=[],total=76,totalLockers=76,filter='all';window.settings={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const escJs=s=>String(s??'').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\n/g,' ');
const norm=v=>{v=String(v??'').trim().toLowerCase().replace(/\s+/g,' ');if(v==='morning'||v==='morning shift')return 'Morning Shift';if(v==='evening'||v==='evening shift')return 'Evening Shift';if(v==='full'||v==='full day'||v==='full day shift')return 'Full Day';return String(v)};
const api=async action=>{const r=await fetch('admin_api.php?action='+encodeURIComponent(action),{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok||d.success===false)throw Error(d.message||'Request failed');return d};
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.style.display='block';clearTimeout(window.__toast);window.__toast=setTimeout(()=>e.style.display='none',2600)}
function conflicts(requested,x){if(!x)return false;const st=String(x.status??'').toLowerCase();if(st!=='assigned'&&st!=='reserved')return false;const s=norm(x.shift);if(requested==='Full Day')return ['Morning Shift','Evening Shift','Full Day'].includes(s);if(requested==='Morning Shift')return ['Morning Shift','Full Day'].includes(s);return ['Evening Shift','Full Day'].includes(s)}
function hours(t){const f=x=>{const [h,m]=String(x||'').split(':').map(Number);if(!Number.isFinite(h))return String(x||'');return `${(h%12)||12}:${String(m||0).padStart(2,'0')} ${h>=12?'PM':'AM'}`};if(t==='Morning Shift')return `${f(window.settings.opening_time||'08:00')} – ${f(window.settings.morning_end||'14:00')}`;if(t==='Evening Shift')return `${f(window.settings.evening_start||'14:00')} – ${f(window.settings.closing_time||'20:00')}`;return `${f(window.settings.opening_time||'08:00')} – ${f(window.settings.closing_time||'20:00')}`}
function load(){api('seats').then(d=>{rows=d.seats||[];lockers=d.lockers||[];total=Number(d.total_seats||76);totalLockers=Number(d.total_lockers||76);window.settings=d.settings||{};render();renderLockers()}).catch(e=>{document.getElementById('shifts').innerHTML=`<div class="empty">Could not load live data: ${esc(e.message)}</div>`})}
function render(){const shifts=[['Morning Shift','m'],['Evening Shift','e'],['Full Day','f']];let html='';shifts.forEach(([title,key])=>{const relevant=rows.filter(x=>conflicts(title,x));const by={};relevant.forEach(x=>{const n=String(x.seat_no).replace(/^S-0*/i,'');const sx=norm(x.shift);if(!by[n]||sx==='Full Day'||sx===title)by[n]=x});const occ=Object.values(by).filter(x=>String(x.status).toLowerCase()==='assigned').length;const res=Object.values(by).filter(x=>String(x.status).toLowerCase()==='reserved').length;const free=Math.max(0,total-occ-res);html+=`<section class="shift"><div class="shift-head"><div class="shift-title"><i class="dot ${key}"></i><div><b>${title}</b><small>${hours(title)}</small></div></div><div class="shift-stat">${free} Free · ${occ} Occupied${res?' · '+res+' Reserved':''}</div></div><div class="seat-grid">`;for(let start=1;start<=total;start+=20){const end=Math.min(total,start+19);html+=`<div class="row-label">ROW ${String.fromCharCode(65+Math.floor((start-1)/20))}</div>`;for(let n=start;n<=end;n++){const x=by[String(n)];const st=x?(String(x.status).toLowerCase()==='reserved'?'reserved':'occupied'):'available';const sx=x?norm(x.shift):title;const cc=sx==='Morning Shift'?'morning':sx==='Evening Shift'?'evening':'full';const label=x?(x.name||x.member_code||'Booked'):'Available';const search=(n+' '+label+' '+(x?.member_code||''));html+=`<button type="button" class="seat ${st} ${st==='occupied'?cc:''}" data-search="${esc(search)}" data-state="${st}" title="${esc('Seat '+n+' · '+label+' · '+sx)}" onclick="openSeat(${x?Number(x.id):0},${n},'${escJs(x?norm(x.shift):title)}')"><span class="chair">💺</span><b>${n}</b><small>${esc(label)}</small></button>`}if(end<total)html+='<div class="aisle"></div>'}html+='</div></section>'});document.getElementById('shifts').innerHTML=html;document.getElementById('capacity').textContent=total+' SEATS';renderKpis();applyFilters()}
function renderKpis(){const assigned=rows.filter(x=>String(x.status).toLowerCase()==='assigned');const reserved=rows.filter(x=>String(x.status).toLowerCase()==='reserved');const used=new Set([...assigned,...reserved].map(x=>String(x.seat_no).replace(/^S-0*/i,''))).size;const free=Math.max(0,total-used);const fill=total?Math.round(assigned.length/total*100):0;const la=lockers.filter(x=>String(x.status).toLowerCase()==='assigned').length;const lf=Math.max(0,totalLockers-la);document.getElementById('kpis').innerHTML=`<div class="kpi"><div class="kpi-top"><span class="kpi-label">Total Seats</span><span class="kpi-icon">💺</span></div><div class="kpi-value">${total}</div><div class="kpi-foot">Library capacity</div></div><div class="kpi"><div class="kpi-top"><span class="kpi-label">Available</span><span class="kpi-icon">✓</span></div><div class="kpi-value">${free}</div><div class="kpi-foot">Ready for booking</div></div><div class="kpi"><div class="kpi-top"><span class="kpi-label">Occupied</span><span class="kpi-icon">●</span></div><div class="kpi-value">${assigned.length}</div><div class="kpi-foot">${fill}% current allocation</div></div><div class="kpi"><div class="kpi-top"><span class="kpi-label">Reserved</span><span class="kpi-icon">◆</span></div><div class="kpi-value">${reserved.length}</div><div class="kpi-foot">Pending reservations</div></div><div class="kpi"><div class="kpi-top"><span class="kpi-label">Free Lockers</span><span class="kpi-icon">🔐</span></div><div class="kpi-value">${lf}</div><div class="kpi-foot">${la} assigned of ${totalLockers}</div></div>`}
function applyFilters(){const q=(document.getElementById('search')?.value||'').toLowerCase().trim();document.querySelectorAll('.seat').forEach(e=>{const okText=!q||(e.dataset.search||'').toLowerCase().includes(q);const okState=filter==='all'||e.dataset.state===filter;e.classList.toggle('dim',!(okText&&okState));e.classList.toggle('hit',!!q&&okText&&okState)})}
function setFilter(f,b){filter=f;document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');applyFilters()}
function openSeat(id,n,shift){const cur=id?rows.find(x=>Number(x.id)===Number(id)):null;const booked=!!cur;const name=cur?.name||'';const code=cur?.member_code||'';const initials=(name||'M').trim().charAt(0).toUpperCase();let profile=booked?`<div class="profile"><div class="profile-avatar">${esc(initials)}</div><div class="profile-main"><div class="profile-name">${esc(name||'Member')}</div><div class="profile-meta">${esc(code||'Member ID unavailable')}</div><div class="profile-tags"><span>SEAT ${esc(n)}</span><span>${esc(shift)}</span></div></div><span class="booked">BOOKED</span></div>`:'';let details=booked?`<div class="grid2"><div class="field"><label>MEMBER</label><input value="${esc(name)}" readonly></div><div class="field"><label>MEMBER ID</label><input value="${esc(code)}" readonly></div><div class="field"><label>SEAT</label><input value="${esc(n)}" readonly></div><div class="field"><label>SHIFT</label><input value="${esc(shift)}" readonly></div><div class="field"><label>START DATE</label><input value="${esc(cur?.start_date||'—')}" readonly></div><div class="field"><label>VALID TILL</label><input value="${esc(cur?.end_date||'—')}" readonly></div></div>`:`<div class="grid2"><div class="field"><label>SEAT</label><input value="${esc(n)}" readonly></div><div class="field"><label>SHIFT</label><input value="${esc(shift)}" readonly></div></div>`;const profileBtn=booked&&cur?.member_id?`<button class="btn" onclick="location.href='member_profile.php?id=${encodeURIComponent(cur.member_id)}'">View Member Profile</button>`:'';document.getElementById('modal').innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><h3>${booked?'Booked Seat':'Assign Seat'} · ${esc(n)}</h3><button class="close" onclick="closeModal()">×</button></div><div class="form">${profile}${details}<div class="field"><label>MEMBER ID / MEMBER CODE</label><input id="seatMember" value="${esc(code)}" placeholder="Example: MEM-001"></div><div class="modalfoot">${profileBtn}<button class="btn" onclick="closeModal()">Cancel</button>${booked?`<button class="btn" onclick="releaseSeat(${Number(id)})">Release</button>`:''}<button class="btn primary" onclick="saveSeat(${id||0},${n},'${escJs(shift)}')">${booked?'Update Assignment':'Assign Seat'}</button></div></div></div></div>`}
async function saveSeat(id,n,shift){const m=document.getElementById('seatMember').value.trim();if(!m)return toast('Member ID / code is required.');const f=new FormData();f.append('seat_no',n);f.append('shift',shift);f.append('member_id',m);if(id)f.append('id',id);try{const r=await fetch('admin_api.php?action=assign_seat',{method:'POST',body:f,credentials:'same-origin'});const d=await r.json();if(!r.ok||d.success===false)throw Error(d.message||'Could not save seat');closeModal();toast(d.message||'Seat saved successfully');load()}catch(e){toast(e.message)}}
async function releaseSeat(id){if(!confirm('Release this seat?'))return;try{const r=await fetch('admin_api.php?action=release_seat',{method:'POST',body:new URLSearchParams({id:String(id)}),credentials:'same-origin'});const d=await r.json();if(!r.ok||d.success===false)throw Error(d.message||'Could not release seat');closeModal();toast(d.message||'Seat released');load()}catch(e){toast(e.message)}}
function closeModal(){document.getElementById('modal').innerHTML=''}
function renderLockers(){const box=document.getElementById('lockerLayout');const assigned={};lockers.forEach(x=>assigned[String(x.locker_no)]=x);let h='';for(let n=1;n<=totalLockers;n++){const x=assigned[String(n)];const st=x?(String(x.status).toLowerCase()==='expired'?'expired':'occupied'):'available';h+=`<button type="button" class="locker ${st}" title="${esc(x?('Locker '+n+' · '+(x.name||'Assigned')):('Locker '+n+' · Available'))}" onclick="openLocker(${n},${x?Number(x.id):0})">${n}</button>`}box.innerHTML=h;const active=lockers.filter(x=>String(x.status).toLowerCase()==='assigned').length;const expired=lockers.filter(x=>String(x.status).toLowerCase()==='expired').length;document.getElementById('lockerSummary').textContent=`${Math.max(0,totalLockers-active-expired)} FREE · ${active} USED`;const holder=document.getElementById('lockerHolders');holder.innerHTML=lockers.length?lockers.map(x=>`<div class="holder"><span class="avatar">🔐</span><div class="holder-main"><b>Locker ${esc(x.locker_no)} · ${esc(x.name||'Unknown')}</b><small>${esc(x.member_code||'')} · ${esc(x.status)} · ${esc(x.end_date||'No end date')}</small></div><button class="release" onclick="releaseLocker(${Number(x.id)})">×</button></div>`).join(''):'<div class="empty">No locker assignments.</div>'}
function openLocker(no,id){const cur=id?lockers.find(x=>Number(x.id)===Number(id)):null;const today=new Date().toISOString().slice(0,10);document.getElementById('modal').innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><h3>${cur?'Edit Locker':'Assign Locker'} · ${esc(no)}</h3><button class="close" onclick="closeModal()">×</button></div><div class="form"><div class="grid2"><div class="field"><label>LOCKER NUMBER</label><input id="lockerNo" type="number" min="1" max="${totalLockers}" value="${esc(no)}"></div><div class="field"><label>MEMBER ID / CODE</label><input id="lockerMember" value="${esc(cur?.member_code||'')}" placeholder="MEM-001"></div><div class="field"><label>START DATE</label><input id="lockerStart" type="date" value="${esc(cur?.start_date||today)}"></div><div class="field"><label>END DATE</label><input id="lockerEnd" type="date" value="${esc(cur?.end_date||'')}"></div></div><div class="modalfoot"><button class="btn" onclick="closeModal()">Cancel</button>${cur?`<button class="btn" onclick="releaseLocker(${Number(id)})">Release</button>`:''}<button class="btn primary" onclick="saveLocker(${Number(id||0)})">Save Locker</button></div></div></div></div>`}
async function saveLocker(id){const locker=document.getElementById('lockerNo').value.trim(),member=document.getElementById('lockerMember').value.trim();if(!locker||!member)return toast('Locker number and member are required.');const fd=new FormData();fd.append('locker_no',locker);fd.append('member_id',member);fd.append('start_date',document.getElementById('lockerStart').value);fd.append('end_date',document.getElementById('lockerEnd').value);if(id)fd.append('id',id);try{const r=await fetch('admin_api.php?action=assign_locker',{method:'POST',body:fd,credentials:'same-origin'});const d=await r.json();if(!r.ok||d.success===false)throw Error(d.message||'Could not save locker');closeModal();toast(d.message||'Locker saved');load()}catch(e){toast(e.message)}}
async function releaseLocker(id){if(!confirm('Release this locker?'))return;try{const r=await fetch('admin_api.php?action=release_locker',{method:'POST',body:new URLSearchParams({id:String(id)}),credentials:'same-origin'});const d=await r.json();if(!r.ok||d.success===false)throw Error(d.message||'Could not release locker');closeModal();toast(d.message||'Locker released');load()}catch(e){toast(e.message)}}
load();
</script></body></html>
